# frozen_string_literal: true

require_relative 'content_helper'

SYNTAX_MOBILE_AUTOMATIONS = %w[android ios cross_platform].freeze

# Projects are generated by spec_helper's before(:all), so the file list is read inside the
# examples (after generation), never when this file loads.
describe 'Ruby syntax validation' do
  def generated_ruby_files(project_name)
    Dir.glob('**/*.rb', base: project_name).sort
  end

  def syntax_error_for(content)
    RubyVM::InstructionSequence.compile(content)
    nil
  rescue SyntaxError => e
    e.message
  end

  FRAMEWORKS.each do |framework|
    AUTOMATION_TYPES.each do |automation|
      { 'with examples' => true, 'without examples' => false }.each do |label, examples|
        it "generates only valid Ruby with frozen_string_literal for #{framework} and #{automation} (#{label})" do
          project_name = ensure_project(framework:, automation:, examples:)
          files = generated_ruby_files(project_name)

          expect(files).not_to be_empty
          aggregate_failures do
            files.each do |relative|
              content = File.read(File.join(project_name, relative))
              expect(syntax_error_for(content)).to be_nil, "#{project_name}/#{relative} has a syntax error"
              expect(content).to have_frozen_string_literal, "#{project_name}/#{relative} lacks frozen_string_literal"
            end
          end
        end
      end
    end

    SYNTAX_MOBILE_AUTOMATIONS.each do |automation|
      it "#{framework}_#{automation} wait_helper has the mobile gestures and no web-only methods" do
        content = File.read(File.join(ensure_project(framework:, automation:), 'helpers/wait_helper.rb'))
        expect(content).to include("'mobile: swipeGesture'").and include('def scroll_to(')
        expect(content).not_to include('def drag_and_drop(')
      end
    end
  end
end
